CREATE OR REPLACE FUNCTION public.fp4436_cabin_oem_numbering_approved(c public.elimfilters_catalog)
RETURNS boolean LANGUAGE sql STABLE AS $approval$
SELECT coalesce(c.id=31947 AND c.sku='EC37516' AND c.codigo_base='64319127516' AND c.duty='LIGHT_DUTY' AND c.filter_type='cabin' AND c.canonical_source_brand='MANN-FILTER' AND c.canonical_source_code='FP4436' AND c.canonical_source_status='VERIFIED' AND c.canonical_source_url='https://www.mann-filter.com/en/catalog/search-results/product.html/fp4436_mann-filter.html'
AND c.enrichment_data->'codigo_base_governance' @> '{"origin_group":"EUROPEAN","approved_manufacturer":"BMW","approved_codigo_base":"64319127516","approved_source_column":"OEM_CODES","primary_manufacturer_verified":true,"mann_code_collision_verified":true,"collision_canonical_code":"FP4436","oem_base_verified":true}'::jsonb
AND c.enrichment_data->'codigo_base_governance'->'approved_cabin_oem_numbering' @> '{"case_id":"FP4436_CABIN_OEM_NUMBERING_20261015","original_sku":"EA34436","mann_sha256":"ea175532b70ba441ee6222bae1504a9f36350003ab7f632e08f663b39cbc9af8","oem_sha256":"98b7a0f80192680623344769ebdb38f197a6cbe059492ac221b753124712defc","mann_url":"https://www.mann-filter.com/en/catalog/search-results/product.html/fp4436_mann-filter.html","oem_url":"https://shop.mini.co.uk/product/genuine-microfilter-activated-carbon-container-cabin-air-filter-64-31-9-127-516"}'::jsonb,false);
$approval$;
